ss": {"is_oa": true, "oa_status": "green", "oa_url": "https://arxiv.org/pdf/2510.01530", "any_repository_has_fulltext": true}, "primary_location": {"id": "pmh:oai:arXiv.org:2510.01530", "doi": null, "is_oa": true, "landing_page_url": "http://arxiv.org/abs/2510.01530", "pdf_url": "https://arxiv.org/pdf/2510.01530", "source": {"id": "https://openalex.org/S4306400194", "display_name": "arXiv (Cornell University)", "issn_l": "2331-8422", "issn": ["2331-8422"], "is_oa": true, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I205783295", "host_organization_name": "Cornell University", "host_organization_lineage": ["https://openalex.org/I205783295"], "host_organization_lineage_names": [], "type": "repository"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": null, "raw_type": "text"}, "abstract": "High-assurance reasoning, particularly in critical domains such as law and medicine, requires conclusions that are accurate, verifiable, and explicitly grounded in evidence. This reasoning relies on premises codified from rules, statutes, and contracts, inherently involving defeasible or non-monotonic logic due to numerous exceptions, where the introduction of a single fact can invalidate general rules, posing significant challenges. While large language models (LLMs) excel at processing natural language, their capabilities in standard inference tasks do not translate to the rigorous reasoning required over high-assurance text guidelines. Core reasoning challenges within such texts often manifest specific logical structures involving negation, implication, and, most critically, defeasible rules and exceptions. In this paper, we propose a novel neurosymbolically-grounded architecture called LOGicalThought (LogT) that uses an advanced logical language and reasoner in conjunction with an LLM to construct a dual symbolic graph context and logic-based context. These two context representations transform the problem from inference over long-form guidelines into a compact grounded evaluation. Evaluated on four multi-domain benchmarks against four baselines, LogT improves overall performance by 11.84% across all LLMs. Performance improves significantly across all three modes of reasoning: by up to +10.2% on negation, +13.2% on implication, and +5.5% on defeasible reasoning compared to the strongest baseline."}]", "excerpt_truncated": true, "source_sha256": "506b1ee94ae33b771fcee55ce8053a5c68cf1644c25ddea7101eec3642925416", "verification_required": true, "topic_domain": "assumption_challenge", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.52202/085713-1149", "openalex:W4414588091", "openalex:W7203845197", "arxiv:2505.20047", "arxiv:2510.01530"], "source_candidates": ["https://doi.org/10.52202/085713-1149", "https://arxiv.org/pdf/2505.20047", "https://arxiv.org/pdf/2510.01530"], "source_candidate_identities": {}}
